const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];

function pad(n) { return String(n).padStart(2, '0'); }
function daysInMonth(year, m) { return new Date(year, m + 1, 0).getDate(); }
function sundayOffset(year, m) { return new Date(year, m, 1).getDay(); }

function buildMonth(year, m) {
  const wrap = document.createElement('section');
  wrap.className = 'month';
  wrap.setAttribute('aria-label', MONTH_NAMES[m] + ' ' + year);
  const h = document.createElement('h3');
  h.textContent = MONTH_NAMES[m] + ' ' + year;
  wrap.appendChild(h);
  const dow = document.createElement('div');
  dow.className = 'dow';
  ['SU','MO','TU','WE','TH','FR','SA'].forEach(function (d) {
    const s = document.createElement('span'); s.textContent = d; dow.appendChild(s);
  });
  wrap.appendChild(dow);
  const grid = document.createElement('div');
  grid.className = 'days';
  for (let i = 0; i < sundayOffset(year, m); i++) {
    const e = document.createElement('span'); e.className = 'day empty'; e.setAttribute('aria-hidden','true'); grid.appendChild(e);
  }
  const last = daysInMonth(year, m);
  let hadOpen = false;
  for (let d = 1; d <= last; d++) {
    const cell = document.createElement('span');
    const iso = year + '-' + pad(m + 1) + '-' + pad(d);
    cell.className = 'day';
    cell.setAttribute('data-date', iso);
    cell.textContent = d;
    if (OPEN.indexOf(iso) !== -1) { cell.classList.add('open'); hadOpen = true; }
    if (BUSY.indexOf(iso) !== -1) cell.classList.add('busy');
    grid.appendChild(cell);
  }
  wrap.appendChild(grid);
  if (hadOpen) {
    const lab = document.createElement('span');
    lab.className = 'spaces-label';
    lab.textContent = 'spaces';
    wrap.appendChild(lab);
  }
  return wrap;
}

function drawYear(container) {
  const year = parseInt(container.getAttribute('data-year'), 10);
  container.innerHTML = '';
  for (let m = 0; m < 12; m++) container.appendChild(buildMonth(year, m));
}

function setupTabs() {
  const tabs = document.querySelectorAll('.year-tabs [role="tab"]');
  tabs.forEach(function (tab) {
    tab.addEventListener('click', function () {
      tabs.forEach(function (t) {
        t.setAttribute('aria-selected', t === tab ? 'true' : 'false');
        const panel = document.getElementById(t.getAttribute('aria-controls'));
        if (panel) panel.hidden = t !== tab;
      });
    });
  });
}

function setupHeroRotator() {
  const box = document.querySelector('.hero-rotator');
  if (!box) return;
  const slides = box.querySelectorAll('img');
  if (slides.length < 2) return;
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let i = 0;
  function show() {
    const two = window.matchMedia('(min-width: 700px)').matches;
    const count = two ? Math.min(2, slides.length) : 1;
    slides.forEach(function (img) { img.classList.remove('is-active'); });
    for (let n = 0; n < count; n++) {
      slides[(i + n) % slides.length].classList.add('is-active');
    }
  }
  show();
  if (reduce) return;
  setInterval(function () {
    i = (i + 1) % slides.length;
    show();
  }, 5000);
}




function setupTourSeasonAnalytics() {
  if (typeof gtag !== 'function') return;
  var path = (location.pathname || '').toLowerCase();
  var page = path.split('/').pop() || 'index.html';
  if (!page || page.indexOf('.') === -1) page = 'index.html';

  var pageEvents = {
    'pricing.html': 'view_pricing',
    'dates.html': 'view_dates',
    'tour-inspiration.html': 'view_tour_inspiration',
    'tours.html': 'view_tour_inspiration',
    'day-trips.html': 'view_day_trips',
    'contact.html': 'view_contact',
    'happy-customers.html': 'view_happy_customers'
  };
  if (pageEvents[page]) {
    gtag('event', pageEvents[page], {
      event_category: 'tour_season',
      page_path: location.pathname + location.search
    });
  }

  document.querySelectorAll('a.btn').forEach(function (a) {
    a.addEventListener('click', function () {
      var href = (a.getAttribute('href') || '').toLowerCase();
      var label = (a.textContent || '').trim().slice(0, 80);
      var name = 'cta_click';
      if (href.indexOf('contact') !== -1 || /enquir/i.test(label)) name = 'enquire_click';
      else if (href.indexOf('pricing') !== -1 || /price/i.test(label)) name = 'pricing_click';
      else if (href.indexOf('dates') !== -1) name = 'dates_click';
      else if (href.indexOf('tour') !== -1 || href.indexOf('tours') !== -1) name = 'tour_click';
      gtag('event', name, {
        event_category: 'tour_season',
        event_label: label,
        link_url: href
      });
    });
  });

  var form = document.getElementById('enquire-form');
  if (form) {
    form.addEventListener('submit', function () {
      gtag('event', 'enquire_submit', {
        event_category: 'tour_season',
        event_label: 'contact_form'
      });
    });
  }
}




function setupCernaOutboundAnalytics() {
  if (typeof gtag !== 'function') return;
  var links = document.querySelectorAll('a.js-cerna-outbound, a[href*="cernabizuterie"]');
  links.forEach(function (a) {
    a.addEventListener('click', function () {
      var href = a.href || a.getAttribute('href') || '';
      gtag('event', 'cerna_link_click', {
        event_category: 'outbound',
        event_label: 'cerna_bizuterie',
        link_url: href,
        link_page: location.pathname
      });
    });
  });
}

function setupYtScrollAndEnlarge() {
  var cards = document.querySelectorAll('.yt-card[data-yt-id]');
  if (!cards.length) return;

  function post(iframe, func) {
    if (!iframe || !iframe.contentWindow) return;
    iframe.contentWindow.postMessage(JSON.stringify({ event: 'command', func: func, args: [] }), '*');
  }

  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        var iframe = entry.target.querySelector('iframe');
        if (!iframe) return;
        if (entry.isIntersecting && entry.intersectionRatio >= 0.4) post(iframe, 'playVideo');
        else post(iframe, 'pauseVideo');
      });
    }, { threshold: [0, 0.4, 0.75] });
    cards.forEach(function (card) {
      var host = card.querySelector('[data-yt-host]');
      if (host) io.observe(host);
    });
  }

  var dlg = document.getElementById('yt-lightbox');
  var host = dlg ? dlg.querySelector('[data-yt-lightbox-host]') : null;
  cards.forEach(function (card) {
    var btn = card.querySelector('[data-yt-enlarge]');
    if (!btn || !dlg || !host) return;
    btn.addEventListener('click', function () {
      var id = card.getAttribute('data-yt-id');
      host.innerHTML = '<iframe title="Enlarged video" src="https://www.youtube.com/embed/' + id + '?autoplay=1&rel=0&modestbranding=1" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>';
      if (typeof dlg.showModal === 'function') dlg.showModal();
      else dlg.setAttribute('open', '');
    });
  });
  if (dlg) {
    dlg.addEventListener('close', function () { if (host) host.innerHTML = ''; });
  }
}

function setupHistoryAutoplay() {
  var videos = document.querySelectorAll('video.history-autoplay');
  if (!videos.length) return;
  if (!('IntersectionObserver' in window)) return;
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      var v = entry.target;
      if (entry.isIntersecting && entry.intersectionRatio >= 0.45) {
        var playPromise = v.play();
        if (playPromise && playPromise.catch) playPromise.catch(function () {});
      } else {
        v.pause();
      }
    });
  }, { threshold: [0, 0.45, 0.75] });
  videos.forEach(function (v) {
    v.muted = true;
    io.observe(v);
  });
}

function setupTourSlideshows() {
  const rows = document.querySelectorAll('[data-slideshow]');
  if (!rows.length) return;
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  rows.forEach(function (row) {
    let images;
    try { images = JSON.parse(row.getAttribute('data-images') || '[]'); }
    catch (e) { return; }
    if (!images.length) return;
    const imgs = row.querySelectorAll('.slide-slot img');
    if (!imgs.length) return;
    let offset = 0;
    function paint() {
      imgs.forEach(function (img, slot) {
        const src = images[(offset + slot) % images.length];
        if (img.getAttribute('data-full') === src) return;
        img.classList.add('is-fading');
        window.setTimeout(function () {
          img.setAttribute('data-full', src);
          if (typeof window.applyResponsiveSrc === 'function') window.applyResponsiveSrc(img, src);
          else img.src = src;
          img.classList.remove('is-fading');
        }, 200);
      });
    }
    paint();
    if (reduce || images.length <= 3) return;
    // Advance by a full row so a photo never slides from one box into another
    window.setInterval(function () {
      offset = (offset + imgs.length) % images.length;
      paint();
    }, 4500);
  });
}

window.applyResponsiveSrc = function (img, original) {
  var map = window.RESPONSIVE_IMAGES || {};
  var info = map[original];
  if (!info || !info.widths || !info.widths.length) {
    img.removeAttribute('srcset');
    img.src = original;
    return;
  }
  var stem = original.replace(/\.[^.]+$/, '');
  function list(ext) {
    return info.widths.map(function (w) { return stem + '-' + w + '.' + ext + ' ' + w + 'w'; }).join(', ');
  }
  var fallbackW = info.widths[info.widths.length - 1];
  for (var i = 0; i < info.widths.length; i++) {
    if (info.widths[i] >= 960) { fallbackW = info.widths[i]; break; }
  }
  img.srcset = list('jpg');
  img.src = stem + '-' + fallbackW + '.jpg';
  if (info.w) img.setAttribute('width', String(info.w));
  if (info.h) img.setAttribute('height', String(info.h));
  var picture = img.parentNode && img.parentNode.nodeName === 'PICTURE' ? img.parentNode : null;
  var source = picture ? picture.querySelector('source[type="image/webp"]') : null;
  if (source) source.setAttribute('srcset', list('webp'));
};

document.addEventListener('DOMContentLoaded', function () {
  document.querySelectorAll('.year-grid[data-year]').forEach(drawYear);
  setupTabs();
  setupHeroRotator();
  setupTourSlideshows();
  setupTourSeasonAnalytics();
  setupCernaOutboundAnalytics();
  setupHistoryAutoplay();
  setupYtScrollAndEnlarge();
});
